{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 공공자전거 이용자 과실 파손 시 시의 수리·배상 요구 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 자전거이용 활성화에 관한 조례 제12조의2 제6항에 따르면, 시장은 공공자전거 이용자가 고의 또는 과실 등의 귀책사유로 공공자전거의 도난·분실·파손 등의 손실을 초래한 경우 이용자에게 원상복구 또는 손해배상을 요구할 수 있다. 따라서 이용자 과실로 공공자전거가 파손된 경우 시는 수리(원상복구)나 배상을 요구할 수 있다.",
          "b_ids": "자전거:제12조의2제6항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
